import React from 'react';
import { useHistory } from 'react-router-dom';
import styled from 'styled-components';

const DashboardPage = ({ lorryDetails }) => {
  const history = useHistory(); // For navigation

  // Function to handle navigation
  const handleNavigation = (section) => {
    if (section === 'employee') {
      history.push(`/employee/${lorryDetails.id}`);
    } else if (section === 'fuel') {
      history.push(`/fuel/${lorryDetails.id}`);
    } else if (section === 'point') {
      history.push(`/point/${lorryDetails.id}`);
    }
  };

  return (
    <Container>
      {lorryDetails && (
        <>
          <Header>
            <HeaderLeft>Reg. No: {lorryDetails.registration_number}</HeaderLeft>
            <HeaderCenter>{lorryDetails.owner_name}</HeaderCenter>
            <HeaderRight>Phone: {lorryDetails.owner_phone}</HeaderRight>
          </Header>

          <DashboardOptions>
            <OptionButton onClick={() => handleNavigation('employee')}>Employee</OptionButton>
            <OptionButton onClick={() => handleNavigation('fuel')}>Fuel Details</OptionButton>
            <OptionButton onClick={() => handleNavigation('point')}>Point Details</OptionButton>
          </DashboardOptions>
        </>
      )}
    </Container>
  );
};

export default DashboardPage;


// Styled Components
const Container = styled.div`
  font-family: 'Arial', sans-serif;
  background-color: #f4f4f9;
  padding: 20px;
`;

const Header = styled.div`
  background-color: #2c3e50;
  color: #fff;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px;
  border-radius: 8px;
  margin-bottom: 20px;
`;

const HeaderLeft = styled.div`
  font-size: 18px;
  font-weight: bold;
`;

const HeaderCenter = styled.div`
  font-size: 20px;
  font-weight: 600;
`;

const HeaderRight = styled.div`
  font-size: 16px;
`;

const DashboardOptions = styled.div`
  display: flex;
  gap: 20px;
  margin-top: 20px;
`;

const OptionButton = styled.button`
  background-color: #3498db;
  color: white;
  font-size: 16px;
  padding: 10px 20px;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: #2980b9;
  }
`;
